effect.shader:
// ---- a ponte Nova <-> Node (tools/nodeluzes/gerar.py)
vec2 nvUV;   // o vs_TEXCOORD0 dos programas do Node: o acScreenNorm, ou outro ponto que o passe escolhe
vec3 nvLinear(vec3 c) { return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c)); }
vec3 nvGama(vec3 c) { return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c)); }
// O passe 0: a camada como o Node a guarda (pre-multiplicada, luz linear; o buffer `pre` e sRGB de 8 bits).
vec4 nvCor(vec4 c) { return vec4(nvLinear(c.rgb), c.a); }
vec4 nvEntrada() { vec4 c = texture(inputImg, acScreenNorm); return vec4(nvLinear(c.rgb) * c.a, c.a); }
// A saída do Node (pre-multiplicada, linear, presa a 0..1 como o RT de 8 bits) para a cor reta do Nova. A luz que
// o Node soma acima do alfa (o brilho fora do recorte) vira alfa: a = max(alfa, r, g, b). NaN (0 x infinito na
// conta do Node) vira 0, como no RT de 8 bits dele; a escolha pelo bvec não faz conta com o NaN.
vec4 nvSaida(vec4 p) {
    p = mix(vec4(0.0), min(p, vec4(1.0)), greaterThanEqual(p, vec4(0.0)));
    float a = max(p.a, max(p.r, max(p.g, p.b)));
    return a > 0.0 ? vec4(nvGama(p.rgb / a), a) : vec4(0.0);
}
// A máscara interna do Node (o editor de máscara dele) fica desligada, como no padrão.
#define _use_inner_mask 0
#define _b_clip_mask 0
#define _show_inner_mask 0
// O RenderCommand.DoGaussianBlur do Node (node-gaussian-blur.xml): na METADE da composição, meio-lado = quantidade x
// 0,0475 x a diagonal da composição (em px da metade), sigma = meio-lado x 0,4660. Aqui a mesma gaussiana em UV,
// separável, com no máximo 32 leituras de cada lado (o passo cresce com o sigma; o filtro linear cobre o meio).
vec4 nvGauss(sampler2D t, vec2 eixo, float quant) {
    vec2 metade = 0.5 * acTamanhoDaTela;
    float meio = quant * 0.0475 * length(acTamanhoDaTela) * 0.4660;
    float sigmaUv = dot(eixo, vec2(meio) / metade);
    float texel = dot(eixo, 1.0 / vec2(textureSize(t, 0)));
    if (sigmaUv < 0.05 * texel) return texture(t, acScreenNorm);
    float passo = max(texel, 3.0 * sigmaUv / 32.0);
    vec4 soma = vec4(0.0);
    float pesos = 0.0;
    for (int i = -32; i <= 32; i++) {
        float d = float(i) * passo;
        if (abs(d) > 3.0 * sigmaUv + passo) continue;
        float w = exp(-0.5 * d * d / (sigmaUv * sigmaUv));
        soma += w * texture(t, clamp(acScreenNorm + eixo * d, 0.0, 1.0));
        pesos += w;
    }
    return soma / pesos;
}
// A StreakPyramid do C# (Allocate(1)): o nível 0 = W x H (o pré-filtro); o nível i = (W >> i) x H enquanto
// W >> (i-1) >= 8 — a altura nunca cai. W = a largura em que o efeito roda (a do Node na exportação).
#define nvTela vec2(textureSize(pre, 0))
int nvL() {
    int w = textureSize(pre, 0).x, l = 0;
    for (int i = 1; i < 16; i++) if ((w >> (i - 1)) >= 8) l = i;
    return min(l, 9);
}
// Os programas do Node andam 1/_ScreenSize por leitura em TODO nível: o rastro vem da largura baixa de cada nível
// (o filtro linear entre texels de 2^i px). O motor só reduz a largura até 1/4 (`pack`), então cada nível guarda, num
// buffer mais largo, a reta entre os centros dos texels do nível de verdade: o que o filtro linear do Node leria.
float nvLarg(int i) { return float(textureSize(pre, 0).x >> i); }
vec2 nvCentros(int i, out float f) {
    float w = nvLarg(i);
    float p = acScreenNorm.x * w - 0.5, k = floor(p);
    f = p - k;
    return clamp(vec2(k + 0.5, k + 1.5) / w, 0.5 / w, 1.0 - 0.5 / w);
}

// ---- programa 0 do Node: NodeVideo_Effect_Stylize_LightStreak_0.glsl
vec3 p0_x0;
uvec2 p0_xu0;
vec3 p0_x1;
uvec2 p0_xu4;
float p0_x6;
void p0_main(sampler2D _SourceTexture)
{
    p0_x0.xy = nvUV.xy * nvTela.xy;
    p0_xu0.xy = uvec2(p0_x0.xy);
    p0_xu4.xy = p0_xu0.xy + uvec2(uint(0u), 1u);
    p0_x0.xy = vec2(p0_xu0.xy);
    p0_x0.xy = p0_x0.xy / nvTela.xy;
    p0_x1.xyz = texture(_SourceTexture, p0_x0.xy).xyz;
    p0_x0.xy = vec2(p0_xu4.xy);
    p0_x0.xy = p0_x0.xy / nvTela.xy;
    p0_x0.xyz = texture(_SourceTexture, p0_x0.xy).xyz;
    p0_x0.xyz = p0_x0.xyz + p0_x1.xyz;
    p0_x0.xyz = p0_x0.xyz * vec3(0.5, 0.5, 0.5);
    p0_x6 = max(p0_x0.z, p0_x0.y);
    p0_x6 = max(p0_x6, p0_x0.x);
    p0_x1.x = p0_x6 + (-_threshold);
    p0_x6 = max(p0_x6, 9.99999975e-06);
    p0_x1.x = max(p0_x1.x, 0.0);
    p0_x6 = p0_x1.x / p0_x6;
    fragColor.xyz = vec3(p0_x6) * p0_x0.xyz;
    fragColor.w = 1.0;
    return;
}

// ---- programa 1 do Node: NodeVideo_Effect_Stylize_LightStreak_1.glsl
vec3 p1_x0;
vec4 p1_x1;
vec3 p1_x2;
float p1_x9;
void p1_main(sampler2D _InputTexture)
{
    p1_x0.z = nvUV.y;
    p1_x9 = float(1.0) / nvTela.x;
    p1_x0.xy = (-vec2(p1_x9)) * vec2(5.0, 3.0) + nvUV.xx;
    p1_x1.xyz = texture(_InputTexture, p1_x0.xz).xyz;
    p1_x0.xyz = texture(_InputTexture, p1_x0.yz).xyz;
    p1_x0.xyz = p1_x0.xyz * vec3(2.0, 2.0, 2.0) + p1_x1.xyz;
    p1_x1.x = (-p1_x9) + nvUV.x;
    p1_x1.yw = nvUV.yy;
    p1_x2.xyz = texture(_InputTexture, p1_x1.xy).xyz;
    p1_x0.xyz = p1_x2.xyz * vec3(3.0, 3.0, 3.0) + p1_x0.xyz;
    p1_x1.z = p1_x9 + nvUV.x;
    p1_x2.xy = vec2(p1_x9) * vec2(3.0, 5.0) + nvUV.xx;
    p1_x1.xyz = texture(_InputTexture, p1_x1.zw).xyz;
    p1_x0.xyz = p1_x1.xyz * vec3(3.0, 3.0, 3.0) + p1_x0.xyz;
    p1_x2.z = nvUV.y;
    p1_x1.xyz = texture(_InputTexture, p1_x2.xz).xyz;
    p1_x2.xyz = texture(_InputTexture, p1_x2.yz).xyz;
    p1_x0.xyz = p1_x1.xyz * vec3(2.0, 2.0, 2.0) + p1_x0.xyz;
    p1_x0.xyz = p1_x2.xyz + p1_x0.xyz;
    fragColor.xyz = p1_x0.xyz * vec3(0.0833333358, 0.0833333358, 0.0833333358);
    fragColor.w = 1.0;
    return;
}

// ---- programa 2 do Node: NodeVideo_Effect_Stylize_LightStreak_2.glsl
vec3 p2_x0;
vec4 p2_x1;
vec3 p2_x2;
float p2_x9;
void p2_main(sampler2D _InputTexture, sampler2D _HighTexture)
{
    p2_x0.xyz = texture(_InputTexture, nvUV.xy).xyz;
    p2_x0.xyz = p2_x0.xyz * vec3(0.5, 0.5, 0.5);
    p2_x9 = 1.5 / nvTela.x;
    p2_x1.x = (-p2_x9) + nvUV.x;
    p2_x1.z = p2_x9 + nvUV.x;
    p2_x1.yw = nvUV.yy;
    p2_x2.xyz = texture(_InputTexture, p2_x1.xy).xyz;
    p2_x1.xyz = texture(_InputTexture, p2_x1.zw).xyz;
    p2_x0.xyz = p2_x2.xyz * vec3(0.25, 0.25, 0.25) + p2_x0.xyz;
    p2_x0.xyz = p2_x1.xyz * vec3(0.25, 0.25, 0.25) + p2_x0.xyz;
    p2_x1.xyz = texture(_HighTexture, nvUV.xy).xyz;
    p2_x0.xyz = p2_x0.xyz + (-p2_x1.xyz);
    fragColor.xyz = vec3(vec3(_stretch, _stretch, _stretch)) * p2_x0.xyz + p2_x1.xyz;
    fragColor.w = 1.0;
    return;
}

// ---- programa 3 do Node: NodeVideo_Effect_Stylize_LightStreak_3.glsl
vec3 p3_x0;
vec4 p3_x1;
bvec2 p3_xb1;
vec4 p3_x2;
vec4 p3_x3;
vec4 p3_x4;
vec4 p3_x5;
float p3_x18;
void p3_main(sampler2D _InputTexture)
{
    p3_x0.x = 1.5 / nvTela.x;
    p3_x1.x = (-p3_x0.x) + nvUV.x;
    p3_x1.z = p3_x0.x + nvUV.x;
    p3_x1.yw = nvUV.yy;
    p3_x0.xyz = texture(_InputTexture, p3_x1.xy).xyz;
    p3_x2.xyz = texture(_InputTexture, nvUV.xy).xyz;
    p3_x1.xyz = texture(_InputTexture, p3_x1.zw).xyz;
    p3_x3.xyz = texture(pre, nvUV.xy).xyz;
    p3_x2.xyz = p3_x2.xyz * vec3(0.5, 0.5, 0.5);
    p3_x0.xyz = p3_x0.xyz * vec3(0.25, 0.25, 0.25) + p3_x2.xyz;
    p3_x0.xyz = p3_x1.xyz * vec3(0.25, 0.25, 0.25) + p3_x0.xyz;
    p3_x0.xyz = p3_x0.xyz * nvCor(_tint).xyz;
    p3_x0.xyz = p3_x0.xyz * vec3(_intensity);
    p3_x0.xyz = p3_x0.xyz * vec3(5.0, 5.0, 5.0) + p3_x3.xyz;
    if(int(_use_inner_mask) != 0) {
        p3_xb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        p3_x2.xyz = (p3_xb1.x) ? vec3(1.0, 0.0, 1.0) : p3_x0.xyz;
        p3_x2.w = 1.0;
        p3_x4 = texture(pre, nvUV.xy);
        p3_x5 = (-p3_x4) + vec4(1.0, 1.0, 1.0, 1.0);
        p3_x3.w = 1.0;
        p3_x3 = p3_x3 * p3_x5;
        p3_x2 = p3_x2 * p3_x4 + p3_x3;
        p3_x18 = p3_x4.x * p3_x2.w;
        fragColor.w = (p3_xb1.y) ? p3_x18 : p3_x2.w;
        fragColor.xyz = p3_x2.xyz;
    } else {
        fragColor.xyz = p3_x0.xyz;
        fragColor.w = 1.0;
    }
    return;
}

void main()
{
    nvUV = acScreenNorm;
    if (acPass == 0) { fragColor = nvEntrada(); return; }
    if (acPass == 1) { fragColor = nvGauss(pre, vec2(1.0, 0.0), _blur); return; }
    if (acPass == 2) { fragColor = nvGauss(blurH, vec2(0.0, 1.0), _blur); return; }
    if (acPass == 3) { p0_main(blurred); return; }
    if (acPass == 4) { if (1 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(1, f); nvUV.x = c.x; p1_main(mip0); vec4 a = fragColor; nvUV.x = c.y; p1_main(mip0); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 5) { if (2 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(2, f); nvUV.x = c.x; p1_main(d1); vec4 a = fragColor; nvUV.x = c.y; p1_main(d1); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 6) { if (3 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(3, f); nvUV.x = c.x; p1_main(d2); vec4 a = fragColor; nvUV.x = c.y; p1_main(d2); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 7) { if (4 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(4, f); nvUV.x = c.x; p1_main(d3); vec4 a = fragColor; nvUV.x = c.y; p1_main(d3); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 8) { if (5 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(5, f); nvUV.x = c.x; p1_main(d4); vec4 a = fragColor; nvUV.x = c.y; p1_main(d4); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 9) { if (6 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(6, f); nvUV.x = c.x; p1_main(d5); vec4 a = fragColor; nvUV.x = c.y; p1_main(d5); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 10) { if (7 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(7, f); nvUV.x = c.x; p1_main(d6); vec4 a = fragColor; nvUV.x = c.y; p1_main(d6); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 11) { if (8 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(8, f); nvUV.x = c.x; p1_main(d7); vec4 a = fragColor; nvUV.x = c.y; p1_main(d7); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 12) { if (9 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(9, f); nvUV.x = c.x; p1_main(d8); vec4 a = fragColor; nvUV.x = c.y; p1_main(d8); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 13) { if (8 > nvL() - 1) { fragColor = vec4(0.0); return; } if (8 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(8, f); nvUV.x = c.x; p2_main(d9, d8); vec4 a = fragColor; nvUV.x = c.y; p2_main(d9, d8); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 14) { if (7 > nvL() - 1) { fragColor = vec4(0.0); return; } if (7 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(7, f); nvUV.x = c.x; if (7 == nvL() - 1) p2_main(d8, d7); else p2_main(ua, d7); vec4 a = fragColor; nvUV.x = c.y; if (7 == nvL() - 1) p2_main(d8, d7); else p2_main(ua, d7); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 15) { if (6 > nvL() - 1) { fragColor = vec4(0.0); return; } if (6 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(6, f); nvUV.x = c.x; if (6 == nvL() - 1) p2_main(d7, d6); else p2_main(ub, d6); vec4 a = fragColor; nvUV.x = c.y; if (6 == nvL() - 1) p2_main(d7, d6); else p2_main(ub, d6); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 16) { if (5 > nvL() - 1) { fragColor = vec4(0.0); return; } if (5 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(5, f); nvUV.x = c.x; if (5 == nvL() - 1) p2_main(d6, d5); else p2_main(ua, d5); vec4 a = fragColor; nvUV.x = c.y; if (5 == nvL() - 1) p2_main(d6, d5); else p2_main(ua, d5); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 17) { if (4 > nvL() - 1) { fragColor = vec4(0.0); return; } if (4 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(4, f); nvUV.x = c.x; if (4 == nvL() - 1) p2_main(d5, d4); else p2_main(ub, d4); vec4 a = fragColor; nvUV.x = c.y; if (4 == nvL() - 1) p2_main(d5, d4); else p2_main(ub, d4); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 18) { if (3 > nvL() - 1) { fragColor = vec4(0.0); return; } if (3 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(3, f); nvUV.x = c.x; if (3 == nvL() - 1) p2_main(d4, d3); else p2_main(ua, d3); vec4 a = fragColor; nvUV.x = c.y; if (3 == nvL() - 1) p2_main(d4, d3); else p2_main(ua, d3); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 19) { if (2 > nvL() - 1) { fragColor = vec4(0.0); return; } if (2 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(2, f); nvUV.x = c.x; if (2 == nvL() - 1) p2_main(d3, d2); else p2_main(ub, d2); vec4 a = fragColor; nvUV.x = c.y; if (2 == nvL() - 1) p2_main(d3, d2); else p2_main(ub, d2); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 20) { if (1 > nvL() - 1) { fragColor = vec4(0.0); return; } if (1 > nvL()) { fragColor = vec4(0.0); return; } float f; vec2 c = nvCentros(1, f); nvUV.x = c.x; if (1 == nvL() - 1) p2_main(d2, d1); else p2_main(ua, d1); vec4 a = fragColor; nvUV.x = c.y; if (1 == nvL() - 1) p2_main(d2, d1); else p2_main(ua, d1); fragColor = mix(a, fragColor, f); return; }
    if (acPass == 21) { if (nvL() < 2) p3_main(d1); else p3_main(u1); fragColor = nvSaida(fragColor); return; }
    fragColor = vec4(0.0);
}
